package cups

import (
	"strings"
	"testing"
)

func TestIsValidPrinterName(t *testing.T) {
	valid := []string{
		"Office_LaserJet",
		"printer-1",
		"Canon_MF740C_192.168.1.100",
		"A",
		"Receipt_Printer_99",
		// Names generated by CUPS / PaperCut Mobility Print
		"192.168.1.65_[Office_MacBook_Pro.local](Mobility)",
		"TestPrinter_[@home](Mobility)",
		"HP_ENVY_Photo_7800_series__C58A29_",
		"_192_168_1_65",
		"Büro_Drucker",
		"Printer%20Name",
		strings.Repeat("a", 127),
		// Allowed by CUPS (only Safe Queue Naming in the UI is stricter)
		"Sales&Marketing",
		".Lab",
		"Printer;x",
		"Printer$1",
		"Printer|<x>",
		"Büro\u00a0Drucker",
	}
	for _, name := range valid {
		if !IsValidPrinterName(name) {
			t.Errorf("expected %q to be valid printer name", name)
		}
	}

	invalid := []string{
		"",                        // empty
		"-x",                      // leading dash (flag injection)
		"-p",                      // leading dash
		"--help",                  // leading double dash
		"Printer with spaces",     // spaces
		"Office/LaserJet",         // slash
		"Office\\LaserJet",        // backslash
		"Printer;rm -rf /",        // space and slash
		"Printer\nNewline",        // newline
		"Printer?What",            // question mark
		"Printer#Hash",            // hash
		"Printer'Quote",           // single quote
		"Printer\"Quote",          // double quote
		string(make([]byte, 128)), // too long (> 127)
		strings.Repeat("a", 128),  // too long (> 127)
		" Printer",                // leading space
		"Printer ",                // trailing space
		"Printer\t",               // tab
		"Printer\r",               // carriage return
		"Printer\x00",             // NUL
		"Printer\xff",             // invalid UTF-8
		"../etc/passwd",           // traversal
	}
	for _, name := range invalid {
		if IsValidPrinterName(name) {
			t.Errorf("expected %q to be invalid printer name", name)
		}
	}
}

func TestIsValidPrinterURI(t *testing.T) {
	valid := []string{
		"ipp://192.168.1.50/printers/queue",
		"ipps://secure-printer.local:631/ipp/print",
		"socket://192.168.1.50:9100",
		"lpd://192.168.1.50/queue",
		"usb://HP/LaserJet%20Pro",
		"smb://server/printer",
		"dnssd://Brother%20HL-L2350DW._ipp._tcp.local./?uuid=1234",
		// Real CUPS-generated forms that net/url would reject
		"dnssd://HP%20ENVY%20Photo%207800%20series%20%5BC58A29%5D._ipps._tcp.local./?uuid=688cfb63-25a3-51d8-d6ec-0a7124bf25d3",
		"ipp://[v1.fe80::1+en0]:631/ipp/print",
		"ipp://[2001:db8::1]:631/ipp/print",
		"usb://HP/LaserJet%20Pro?serial=ABC123",
		"smb://workgroup/server/printer",
		"socket://my_printer.local:9100",
		"IPP://192.168.1.50/ipp/print",
		"usb:/dev/usb/lp0",
		// IPP over HTTP(S), as used by PaperCut Mobility Print / Pocket queues
		"http://127.0.0.1:9167/ipp/localhost_9164/4d795f437573746f6d/printers/My%20Custom%20Printer%20Name",
		"http://localhost:9265/printers/d/printer-TwfCDetMisFFfOz4Kyaf/queue-set-9iXv3ga9kB_platform-queue-UZO4QSmYEpRKdePpQzdfPlhOS",
		"https://print.example.com:443/ipp/print",
		// Characters CUPS URIs legitimately use (no shell is involved)
		"ipp://192.168.1.50/printers/q?waitjob=false&waitprinter=false",
		"smb://user:pa$$word@server/printer",
		// Percent-encoded characters are not decoded; they are passed to CUPS literally
		"socket://192.168.1.50:9100/%3B",
		"ipp://host/queue%7Cname%24",
	}
	valid = append(valid, "file:/dev/null", "file:///dev/null")
	for _, uri := range valid {
		if !IsValidPrinterURI(uri) {
			t.Errorf("expected %q to be valid URI", uri)
		}
	}

	invalid := []string{
		"",
		"-v socket://evil",
		"file:///etc/passwd",
		// Only the exact null device is accepted under file:
		"file:/dev/null/../../etc/passwd",
		"file:/dev/null/",
		"file:/dev/null2",
		"file:/dev/nullx/y",
		"file://localhost/dev/null",
		"file:////dev/null",
		"file:/dev//null",
		"file:/dev/./null",
		"file:/dev/%6eull",
		"file:/dev/null?x=1",
		"file:/dev/null#x",
		"file:/dev/null ",
		" file:/dev/null",
		"FILE:/dev/null",
		"file:/dev/zero",
		"file:/dev/disk0",
		"file:/tmp/out.prn",
		"file:dev/null",
		"file:/",
		"exec:///bin/sh",
		"javascript:alert(1)",
		"ftp://evil.com/file",
		"data:text/plain,hello",
		"socket://192.168.1.50\nrm -rf /",
		"socket://192.168.1.50\r",
		"socket://192.168.1.50\t9100",
		"socket://192.168.1.50\x00",
		"socket://192.168.1.50\x1b[2J",
		" -v socket://evil",
		"ipp://",
		"ipp:/",
		"ipp:host",
		"ipp",
		"://host",
		"ipp://host/%zz",
		"ipp://host/%2",
		"ipp://host/%",
		"ipp://host/" + strings.Repeat("a", 1100),
	}
	for _, uri := range invalid {
		if IsValidPrinterURI(uri) {
			t.Errorf("expected %q to be invalid URI", uri)
		}
	}

	// The PaperCut backend prefix must never change the outcome: every URI
	// rejected on its own is still rejected behind "papercut:", and every URI
	// accepted on its own (written without surrounding whitespace) is accepted.
	for _, uri := range invalid {
		if prefixed := "papercut:" + uri; IsValidPrinterURI(prefixed) {
			t.Errorf("prefix must not unblock a rejected URI: %q was accepted", prefixed)
		}
	}
	for _, uri := range valid {
		prefixed := "papercut:" + uri
		want := uri == strings.TrimSpace(uri)
		if got := IsValidPrinterURI(prefixed); got != want {
			t.Errorf("%q: got valid=%v, want %v", prefixed, got, want)
		}
	}
}

// TestPaperCutPrefixCannotBypassRules covers ways the "papercut:" prefix could be
// abused to reach something the device URI rules block.
func TestPaperCutPrefixCannotBypassRules(t *testing.T) {
	accepted := []string{
		"papercut:socket://192.168.1.50:9100",
		"papercut:ipp://printer.local/ipp/print",
		"papercut:ipps://printer.local:443/ipp/print",
		"papercut:http://192.168.1.65:631/printers/Office",
		"papercut:lpd://server/queue",
		"papercut:dnssd://HP%20LaserJet._ipp._tcp.local./",
		"papercut:usb://HP/LaserJet?serial=ABC123",
		"papercut:smb://server/share",
		"papercut:file:/dev/null",
		"papercut:file:///dev/null",
	}
	for _, uri := range accepted {
		if !IsValidPrinterURI(uri) {
			t.Errorf("expected %q to be accepted", uri)
		}
	}

	rejected := []string{
		// Blocked schemes stay blocked
		"papercut:file:///etc/passwd",
		"papercut:file:/etc/shadow",
		"papercut:file:/tmp/out.prn",
		"papercut:file:/dev/zero",
		"papercut:exec:///bin/sh",
		"papercut:javascript:alert(1)",
		"papercut:ftp://evil.com/file",
		"papercut:data:text/plain,hello",
		// Null-device look-alikes stay blocked
		"papercut:file:/dev/null/../../etc/passwd",
		"papercut:file:/dev/null/",
		"papercut:file:/dev/%6eull",
		"papercut:file://localhost/dev/null",
		"papercut:FILE:/dev/null",
		// The prefix alone, or with nothing usable after it
		"papercut:",
		"papercut://",
		"papercut:/",
		"papercut:socket",
		"papercut:socket:",
		"papercut:socket://",
		"papercut://socket://192.168.1.50",
		// Stacked or disguised prefixes
		"papercut:papercut:socket://192.168.1.50",
		"papercut:papercut:file:///etc/passwd",
		"PAPERCUT:socket://192.168.1.50",
		"PaperCut:socket://192.168.1.50",
		"papercut%3Asocket://192.168.1.50",
		"papercut;socket://192.168.1.50",
		"xpapercut:socket://192.168.1.50",
		"socket:papercut:file:///etc/passwd",
		// Whitespace cannot hide what follows the prefix
		"papercut: socket://192.168.1.50",
		"papercut:socket://192.168.1.50 ",
		"papercut: file:///etc/passwd",
		"papercut:file:/dev/null ",
		" papercut:socket://192.168.1.50",
		// Flag injection and control characters
		"papercut:-v socket://evil",
		"papercut:-E",
		"-papercut:socket://192.168.1.50",
		"papercut:socket://192.168.1.50\nrm -rf /",
		"papercut:socket://192.168.1.50\x00",
		"papercut:\tsocket://192.168.1.50",
		"papercut\n:socket://192.168.1.50",
		// Malformed escapes and oversized values
		"papercut:ipp://host/%zz",
		"papercut:ipp://host/%",
		"papercut:ipp://host/" + strings.Repeat("a", 1100),
	}
	for _, uri := range rejected {
		if IsValidPrinterURI(uri) {
			t.Errorf("expected %q to be rejected", uri)
		}
	}
}

func TestIsValidJobID(t *testing.T) {
	valid := []string{
		"1",
		"42",
		"Office_LaserJet-1",
		"printer.local-1234",
		"deskjet_500-99",
		"TestPrinter_[@home](Mobility)-12",
		"192.168.1.65_[Office_MacBook_Pro.local](Mobility)-345",
	}
	for _, id := range valid {
		if !IsValidJobID(id) {
			t.Errorf("expected %q to be valid job ID", id)
		}
	}

	invalid := []string{
		"",
		"-a",
		"-u root",
		"--all",
		"42; rm -rf /",
		"42\nnewline",
		"../../etc/passwd",
		"printer-1-2-3-4-extra",
		"printer-",
		"Printer#x-12",
		"Printer x-12",
		"-12",
		"printer-12a",
	}
	for _, id := range invalid {
		if IsValidJobID(id) {
			t.Errorf("expected %q to be invalid job ID", id)
		}
	}
}

func TestIsValidDriverOrPPD(t *testing.T) {
	valid := []string{
		"everywhere",
		"raw",
		"drv:///sample.drv/generic.ppd",
		"/Library/Printers/PPDs/Contents/Resources/HP.ppd",
		"/System/Library/Printers/Libraries/Generic.ppd",
		"/usr/share/cups/model/laserjet.ppd",
		"Library/Printers/PPDs/Contents/Resources/Kyocera CS 205c.ppd",
		"zebra-zpl.ppd",
		"CNCUPSIRAC5840ZK.ppd",
	}
	for _, d := range valid {
		if !IsValidDriverOrPPD(d) {
			t.Errorf("expected %q to be valid driver", d)
		}
	}

	invalid := []string{
		"",
		"-P /tmp/evil.ppd",
		"-m malicious",
		"/tmp/evil.ppd",
		"/var/tmp/evil.ppd",
		"/Users/someone/Downloads/malicious.ppd",
		"../../../etc/cups/ppd/bad.ppd",
		"drv:///../../tmp/evil.ppd",
		"sub/folder/hack.ppd", // relative directory traversal without whitelisted prefix
		"other/evil.ppd",
		"evil\nnewline",
		"evil;rm -rf /",
	}
	for _, d := range invalid {
		if IsValidDriverOrPPD(d) {
			t.Errorf("expected %q to be invalid driver", d)
		}
	}
}

func TestInspectDangerousPPDDirectives(t *testing.T) {
	dangerousContent := []byte(`*PPD-Adobe: "4.3"
*ModelName: "EvilPrinter"
*cupsFilter: "application/vnd.cups-raster 0 /tmp/malicious_filter"
*FoomaticRIPCommandLine: "touch /tmp/pwned"
`)
	warnings, errors := InspectDangerousPPDDirectives(dangerousContent)
	if len(errors) == 0 {
		t.Errorf("expected error for *FoomaticRIPCommandLine, got 0")
	}
	if len(warnings) == 0 {
		t.Errorf("expected warning for /tmp/malicious_filter, got 0")
	}

	safeContent := []byte(`*PPD-Adobe: "4.3"
*ModelName: "SafePrinter"
*cupsFilter: "application/vnd.cups-raster 0 rastertohp"
`)
	warningsSafe, errorsSafe := InspectDangerousPPDDirectives(safeContent)
	if len(errorsSafe) > 0 || len(warningsSafe) > 0 {
		t.Errorf("expected 0 warnings and errors for safe PPD, got: %v, %v", warningsSafe, errorsSafe)
	}
}

func TestIsValidOptionKeyAndValue(t *testing.T) {
	if !IsValidOptionKey("PageSize") {
		t.Errorf("expected PageSize to be valid option key")
	}
	if !IsValidOptionKey("Duplex") {
		t.Errorf("expected Duplex to be valid option key")
	}
	if IsValidOptionKey("-o") || IsValidOptionKey("key;bad") || IsValidOptionKey("") {
		t.Errorf("expected bad keys to be rejected")
	}

	if !IsValidOptionValue("A4") || !IsValidOptionValue("DuplexNoTumble") {
		t.Errorf("expected valid option values")
	}
	if IsValidOptionValue("-bad") || IsValidOptionValue("val\nnewline") {
		t.Errorf("expected bad option values to be rejected")
	}
}
